\label{ex:sv}
Consider the log-normal stochastic volatility model \cite{Taylor2008}
\[
y_i=\sigma_iZ_i,\qquad \ln\sigma_i^2=\omega+b\ln\sigma_{i-1}^2+\sigma_u u_i,\qquad (Z_i,u_i)^{\top}\sim N(0,I_2)\ \text{i.i.d.},
\]
with $|b|<1$ and parameter $\beta^*=(\omega,b,\sigma_u)^{\top}$. The log-volatility $h_i=\ln\sigma_i^2$ is a stationary Gaussian AR(1) process with mean $\mu=\omega/(1-b)$ and variance $\tau^2=\sigma_u^2/(1-b^2)$, so that $\mathbb{E}[\sigma_i^r]=\exp(r\mu/2+r^2\tau^2/8)$ and, since $\operatorname{Cov}(h_i,h_{i-j})=b^j\tau^2$,
\begin{equation}\label{eq:svcross}
\mathbb{E}\big[\sigma_i^r\sigma_{i-j}^s\big]=\mathbb{E}[\sigma_i^r]\,\mathbb{E}[\sigma_i^s]\exp\Big(\frac{rs\,b^j\tau^2}{4}\Big).
\end{equation}
Following \citet{JacquierPolsonRossi1994} and \citet{AndersenSorensen1996} we use the $d_g=24$ moments
\[
\begin{gathered}
\mathbb{E}|y_i|=\sqrt{2/\pi}\,\mathbb{E}[\sigma_i],\quad \mathbb{E}[y_i^2]=\mathbb{E}[\sigma_i^2],\quad \mathbb{E}|y_i|^3=2\sqrt{2/\pi}\,\mathbb{E}[\sigma_i^3],\quad \mathbb{E}[y_i^4]=3\mathbb{E}[\sigma_i^4],\\
\mathbb{E}|y_iy_{i-j}|=\tfrac2\pi\mathbb{E}[\sigma_i\sigma_{i-j}],\qquad \mathbb{E}[y_i^2y_{i-j}^2]=\mathbb{E}[\sigma_i^2\sigma_{i-j}^2],\qquad j=1,\dots,10,
\end{gathered}
\]
that is, $g(X_i,\beta)=x_i-\mu_{\rm SV}(\beta)$ with $x_i=(|y_i|,y_i^2,|y_i|^3,y_i^4,|y_iy_{i-1}|,\dots,|y_iy_{i-10}|,y_i^2y_{i-1}^2,\dots,y_i^2y_{i-10}^2)^{\top}$ and $\mu_{\rm SV}(\beta)$ the vector of the right-hand sides computed with \eqref{eq:svcross}. Here the Jacobian $G(X_i,\beta)=-\partial\mu_{\rm SV}(\beta)/\partial\beta^{\top}$ does not depend on the data. The data $X_i=(y_i,\dots,y_{i-10})$ are stationary and geometrically mixing but not independent, and the efficient weight is the inverse of the long-run variance of the moments (Section~\ref{sec:dependent}); we use this example in Section~\ref{sec:sv}.

\label{lem:woodbury}
Fix $i\ge1$, write $N=n_0+i-1$, $\Phi=\Phi_{i-1}$, $W=W_{i-1}$, $H=H_{i-1}$, $s=s_i$, and suppose that $\Phi^{\top} W\Phi$ and $\Phi_i^{\top} W_i\Phi_i$ are invertible.
\begin{enumerate}[label=(\alph*),itemsep=2pt]
\item With $\ell=N+s^{\top} Ws$, the inverse of $S_i=(NS_{i-1}+ss^{\top})/(N+1)$ is $W_i=\frac{N+1}{N}\big(W-\frac1\ell Wss^{\top} W\big)$.
\item Suppose that $G(X_i,\bar\beta_{i-1})=z\,\psi^{\top}$ and $s=\varrho z$ with $z\in\mathbb{R}^{d_g}$, $\psi\in\mathbb{R}^{d_\beta}$ and $\varrho\in\mathbb{R}$. For IV-type moments $g=z\,r$ this holds with $z=z_i$, $\psi=\partial_\beta r(X_i,\bar\beta_{i-1})$ and $\varrho=r(X_i,\bar\beta_{i-1})$; for 2SLS weights (Remark~\ref{rem:design}(iv)) it holds with $\varrho=1$. Let
\[
u=\Phi^{\top} Wz,\qquad c_z=z^{\top} Wz,\qquad \ell=N+\varrho^2c_z,\qquad U=[\,u,\ \psi\,]\in\mathbb{R}^{d_\beta\times2},\qquad \mathcal C=\frac1\ell\begin{pmatrix}-N\varrho^2&N\\N&c_z\end{pmatrix}.
\]
Then $I_2+N^{-1}\mathcal CU^{\top} HU$ is invertible and
\begin{equation}\label{eq:woodbury3}
H_i=\frac{N+1}{N}\Big(H-\frac1N\,HU\big(I_2+N^{-1}\mathcal CU^{\top} HU\big)^{-1}\mathcal CU^{\top} H\Big).
\end{equation}
\item (Linear 2SLS.) If $\varrho=1$, then, with $U_2=[\,\psi-u,\ \psi\,]$ and $D=\operatorname{diag}(-\ell,N)$,
\begin{equation}\label{eq:woodbury2}
H_i=\frac{N+1}{N}\Big(H-HU_2\big(D+U_2^{\top} HU_2\big)^{-1}U_2^{\top} H\Big).
\end{equation}
\end{enumerate}

\label{prop:local}
Suppose that Assumption~\ref{ass:smooth} holds on a closed ball $\Theta_0=\bar B(\beta^*,r_0)$.
\begin{enumerate}[label=(\alph*),itemsep=2pt]
\item There are $r_1\in(0,r_0]$ and $\delta_\Phi>0$ such that Assumption~\ref{ass:mono} holds with $c=1/2$ on every compact convex $\Theta\subseteq\bar B(\beta^*,r_1)$ with $\beta^*\in\operatorname{int}\Theta$.
\item In the linear model of Example~\ref{ex:linear}, if Assumption~\ref{ass:smooth} holds on a compact convex $\Theta$, then Assumption~\ref{ass:mono} holds on $\Theta$ with $c=1/2$, for some $\delta_\Phi>0$.
\end{enumerate}

\label{thm:fclt}
Suppose Assumptions~\ref{ass:data}--\ref{ass:steps} hold with $\kappa>\kappa(a)$. Then the partial-sum process
\[
\mathbb B_n(t)=\frac1{\sqrt n}\sum_{i=1}^{\lfloor nt\rfloor}(\beta_i-\beta^*),\qquad t\in[0,1],
\]
converges in distribution in the Skorokhod space $D[0,1]^{d_\beta}$ to $\Sigma^{*1/2}\mathbf B$, where $\mathbf B$ is a standard $d_\beta$-dimensional Brownian motion. More precisely,
\begin{equation}\label{eq:bahadur}
\sup_{t\in[0,1]}\Big\|\mathbb B_n(t)+P^*\frac1{\sqrt n}\sum_{i=1}^{\lfloor nt\rfloor}g(X_i,\beta^*)\Big\|\to0\quad\text{in probability.}
\end{equation}
In particular $\sqrt n(\bar\beta_n-\beta^*)\Rightarrow N(0,\Sigma^*)$, and $\bar\beta_n$ is asymptotically equivalent to the efficient two-step GMM estimator.

\label{rem:2sls}
If $s_i$ is replaced by $z_i$ (Remark~\ref{rem:design}(iv)), then $W_n\to\bar W=\mathbb{E}[zz^{\top}]^{-1}$ and the averaged estimator is asymptotically equivalent to 2SLS-type GMM with weight $\bar W$; in the linear model this is the online 2SLS estimator of \citet{ChenEtAl2025}. Our proofs carry over after replacing $\Omega(\beta)$ by $\mathbb{E}[zz^{\top}]$ in the definition of $\mathcal W$ and $P^*$ by $P(G^*,\bar W)$, and the limit in Theorem~\ref{thm:fclt} then has the sandwich variance $\Sigma_{\bar W}$ of \eqref{eq:sandwich}. Note that in this case $H_n\to(G^{*\top}\bar WG^*)^{-1}\ne\Sigma_{\bar W}$ under heteroskedasticity, so the plug-in intervals of Corollary~\ref{cor:inference}(a) must use the sandwich $H_n\Phi_n^{\top} W_n\hat\Omega_nW_n\Phi_nH_n$ with a running estimate $\hat\Omega_n$ of $\Omega^*$ instead; the random-scaling intervals remain valid without change.

The efficiency of $\bar\beta_n$ is due to the limit of the weight matrix: replacing the preconditioner $H_{i-1}\Phi_{i-1}^{\top} W_{i-1}$ by $K_{i-1}\Phi_{i-1}^{\top} W_{i-1}$ with any invertible $K_{i-1}$ converging to an invertible limit $\bar K$ (for which the corresponding mean field is stable) leads to the same asymptotic variance after averaging \cite{PolyakJuditsky1992}. In particular the first-order version with $K_{i-1}=I$ is asymptotically equivalent to SGMM. The Gauss--Newton choice $K_{i-1}=H_{i-1}$ makes the linearised recursion $\beta_i-\beta^*\approx(1-\gamma_i)(\beta_{i-1}-\beta^*)$, with a contraction that does not depend on the scale or the conditioning of the problem; this makes the algorithm much less sensitive to $\gamma_0$ (Section~\ref{sec:sens}) and provides the variance estimate $H_n$.

\label{lem:precond}
Under Assumptions~\ref{ass:data}, \ref{ass:smooth} and~\ref{ass:steps}, almost surely:
\begin{enumerate}[label=(\alph*),itemsep=2pt]
\item $\operatorname{dist}(\Phi_i,\mathcal G)\to0$, and the eigenvalues of $S_i$ lie in $[\lambda_0/2,2\Lambda]$ for all $i$ large, so that $W_i\in\mathcal W$;
\item for every $\varepsilon'>0$,
\[
\Big\|\Phi_i-\frac1i\sum_{j=1}^i\bar G(\bar\beta_{j-1})\Big\|+\Big\|S_i-\frac1i\sum_{j=1}^i\Omega(\bar\beta_{j-1})\Big\|=O\big(i^{-1/2+\varepsilon'}\big);
\]
\item if $\bar\beta_i\to\beta^*$, then $\Phi_i\to G^*$, $S_i\to\Omega^*$, $W_i\to\Omega^{*-1}$, $H_i\to\Sigma^*$ and $P(\Phi_i,W_i)\to P^*$.
\end{enumerate}

\label{lem:delay}
Let $k\ge1$ be fixed, and let $\xi_i\in\mathbb{R}^d$ be $\mathcal{F}_i$-measurable with $\mathbb{E}[\xi_i\mid\mathcal{F}_{i-k}]=0$ for $i>k$ and $\sup_i\mathbb{E}\|\xi_i\|^p\le c_p$ for some $p\ge2$. For each $r\in\{1,\dots,k\}$, the sequence $(\xi_{r+jk})_{j\ge1}$ is a martingale difference sequence for the filtration $(\mathcal{F}_{r+jk})_{j\ge0}$. Consequently:
\begin{enumerate}[label=(\alph*),itemsep=2pt]
\item $\sum_{i\le n}\xi_i=O(n^{1/2+\varepsilon'})$ almost surely for every $\varepsilon'>0$;
\item for deterministic weights $w_i$, $\mathbb{E}\max_{l\le t}\|\sum_{i\le l}w_i\xi_i\|^p\le C_{p,d,k}\,c_p\big(\sum_{i\le t}w_i^2\big)^{p/2}$;
\item for deterministic weights with $\sum_iw_i^2<\infty$, $\sum_iw_i\xi_i$ converges almost surely;
\item if $\mathbb{E}[\|\xi_i\|^2\mid\mathcal{F}_{i-k}]\le\vartheta_{i-k}$ for $\mathcal{F}_{i-k}$-measurable $\vartheta_{i-k}\ge0$ with $n^{-1}\sum_{i\le n}\vartheta_{i-k}\to0$ in probability, then $n^{-1/2}\max_{l\le n}\|\sum_{i\le l}\xi_i\|\to0$ in probability.
\end{enumerate}

\label{lem:precondLR}
Almost surely:
\begin{enumerate}[label=(\alph*),itemsep=2pt]
\item $\operatorname{dist}(\Phi_i,\mathcal G)\to0$, and the eigenvalues of $S_i$ lie in $[\lambda_0/2,2\Lambda]$ for all $i$ large, so that $W_i=S_i^{-1}\in\mathcal W$;
\item for every $\varepsilon'>0$,
\[
\Big\|\Phi_i-\frac1i\sum_{j=1}^i\bar G(\bar\beta_{j-1})\Big\|+\Big\|S_i-\frac1i\sum_{j=1}^i\Omega_{\rm LR}(\bar\beta_{j-1})\Big\|=O\big(i^{-1/2+\varepsilon'}\big);
\]
\item if $\bar\beta_i\to\beta^*$, then $\Phi_i\to G^*$, $S_i\to\Omega^*_{\rm LR}$, $W_i\to\Omega_{\rm LR}^{*-1}$, $H_i\to\Sigma^*_{\rm LR}=(G^{*\top}\Omega_{\rm LR}^{*-1}G^*)^{-1}$ and $P(\Phi_i,W_i)\to P^*_{\rm LR}=\Sigma^*_{\rm LR}G^{*\top}\Omega_{\rm LR}^{*-1}$;
\item for all $i$ beyond a finite random index, $\|\Phi_i-\Phi_{i-1}\|+\|W_i-W_{i-1}\|\le Ci^{2/\kappa-1}$.
\end{enumerate}
